import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第二十八卦 大过 泽风大过 兑上巽下","description":"周易 - 第二十八卦 大过 泽风大过 兑上巽下","frontmatter":{"title":"第二十八卦 大过 泽风大过 兑上巽下","description":"周易 - 第二十八卦 大过 泽风大过 兑上巽下"},"headers":[],"relativePath":"zh/classics/zhouyi/029.md","filePath":"zh/classics/zhouyi/029.md"}'),l={name:"zh/classics/zhouyi/029.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="大过" tabindex="-1">大过 <a class="header-anchor" href="#大过" aria-label="Permalink to “大过”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>栋桡，利有攸往，亨。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>大过，大者过也。栋桡，本末弱也。刚过而中，巽而说行，利有攸往，乃亨。大过之时义大矣哉！</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>泽灭木，大过；君子以独立不惧，（辶豚）世无闷。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>藉用白茅，无咎。象曰：藉用白茅，柔在下也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>枯杨生稊，老夫得其女妻，无不利。象曰：老夫女妻，过以相与也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>栋桡，凶。象曰：栋桡之凶，不可以有辅也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>栋隆，吉；有它吝。象曰：栋隆之吉，不桡乎下也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>枯杨生华，老妇得士夫，无咎无誉。象曰：枯杨生华，何可久也。老妇士夫，亦可丑也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>过涉灭顶，凶，无咎。象曰：过涉之凶，不可咎也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
